using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_23d1109e917d4617813e6dfee4a87c18;

/// <summary>
/// Subscribes to the underlying AuthenticationStateProvider and persists
/// the user's claims into PersistentComponentState so that the WASM runtime
/// can restore them after prerendering.
/// </summary>
public sealed class PersistingAuthenticationStateProvider : AuthenticationStateProvider, IHostEnvironmentAuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentState;
    private readonly AuthenticationStateProvider _inner;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authStateTask;

    public PersistingAuthenticationStateProvider(
        PersistentComponentState persistentState,
        [FromKeyedServices("inner")] AuthenticationStateProvider inner)
    {
        _persistentState = persistentState;
        _inner = inner;
        _subscription = _persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override async Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        if (_authStateTask is not null)
            return await _authStateTask;

        return await _inner.GetAuthenticationStateAsync();
    }

    public void SetAuthenticationState(Task<AuthenticationState> authenticationStateTask)
    {
        _authStateTask = authenticationStateTask;
    }

    private async Task OnPersistingAsync()
    {
        var authState = await GetAuthenticationStateAsync();
        var principal = authState.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var claims = principal.Claims.Select(c => new ClaimData(c.Type, c.Value)).ToArray();
            _persistentState.PersistAsJson("UserClaims", claims);
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

public record ClaimData(string Type, string Value);

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_23d1109e917d4617813e6dfee4a87c18.Client;

/// <summary>
/// Reads the persisted user claims from PersistentComponentState on WASM startup
/// so that auth state survives the prerender-to-interactive handoff.
/// </summary>
public sealed class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly AuthenticationState _anonymous =
        new(new ClaimsPrincipal(new ClaimsIdentity()));

    private readonly Task<AuthenticationState> _authState;

    public PersistentAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<ClaimData[]>("UserClaims", out var claims) && claims is not null)
        {
            var identity = new ClaimsIdentity(
                claims.Select(c => new Claim(c.Type, c.Value)),
                authenticationType: "Persisted");

            _authState = Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity)));
        }
        else
        {
            _authState = Task.FromResult(_anonymous);
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authState;
}

public record ClaimData(string Type, string Value);

